\documentclass{article}

\usepackage{pgfplots}
\usepackage{tikz}
\usetikzlibrary{arrows}
\usetikzlibrary{intersections}
\usepgfplotslibrary{fillbetween}

\begin{document}

	\pagestyle{empty}
	\definecolor{deepskyblue}{rgb}{0.173,0.447,0.682}
	\definecolor{orangepeel}{rgb}{0.902, 0.624, 0}
	\definecolor{lightyellow}{rgb}{0.953,0.882,0.388}
	\definecolor{darkgreen}{rgb}{0.271, 0.608, 0.463}
	\definecolor{lightblue}{rgb}{0.484,0.702,0.894}
	\definecolor{rustred}{rgb}{0.784,0.392,0.149}
	\definecolor{fadedpink}{rgb}{0.753,0.494,0.643}

	\begin{tikzpicture}
	[
	%%% Base function:
	declare function ={myfunction(\x) = \x*\x*\x-4*\x;},
	%%% Transformed function:
	%%% F(x) = a*f(b*(x-c))+d
	declare function ={newmyfunction(\x,\a,\b,\c,\d) = \a*myfunction(\b*(\x-\c))+\d;}
	]

	\def\ccolor{deepskyblue}

	%% Shift and stretch factors. Please use the  format a*f[b*(x-c)]+d
	\def\a{1} % default should be a=1
	\def\b{1} % default should be b=1
	\def\c{0} % default should be c=0
	\def\d{0} % default should be d=0

	\def\l{-2} % left point of the domain
	\def\r{2} % right point of the domain

	\pgfmathtruncatemacro{\newl}{\l+\c}
	\pgfmathtruncatemacro{\newr}{\r+\c}
	\pgfmathtruncatemacro{\fl}{newmyfunction(\newl,\a,\b,\c,\d)};
	\pgfmathtruncatemacro{\fr}{newmyfunction(\newr,\a,\b,\c,\d)};


	\begin{axis}[
	trig format plots=rad,
	tick label style={font=\footnotesize},
	label style={font=\small},
	legend style={font=\footnotesize},
	tick style={draw=none},
	axis line style = thick,
	axis y line = center,
	axis x line = middle,
	%axis equal,
	grid = both,
	xmin = {-4},
	xmax = {4},
	ymin = {-4},
	ymax = {4},
	xtick = {0},
	ytick = {0},
	%xticklabels = {,,},
	%yticklabels = {,,},
	xlabel = $x$,
	ylabel = {$y$},
	xlabel style={below right},
	ylabel style={above right},
	every axis x label/.style={at={(ticklabel* cs:1.02)}, anchor=west},
	every axis y label/.style={at={(ticklabel* cs:1.02)}, anchor=south}
	]

	% Old graph
%	\node[circle, fill, color=gray, inner sep=1.25pt,
%	label={below, xshift=0pt, opacity=0.5, yshift=0pt:{\small $(-1,0)$}}] at (axis cs:-1,0) {};

	\node[circle, fill, color=gray, inner sep=1.25pt,
	label={right, xshift=0pt, opacity=0.5, yshift=0pt:{\small $(2,-3)$}}] at (axis cs:2,-3) {};

	\plot[domain=(-1:2), samples=100, color=gray, line width=1pt, opacity=0.5, dashed, smooth, variable=\x]
	({\x},{newmyfunction(\x,1,1,1,\d)});

	% New graph
	\node[circle, fill, color=\ccolor, inner sep=1.25pt,
	label={below, xshift=0pt, yshift=0pt:{\small $(-1,0)$}}] at (axis cs:-1,0) {};

	\node[circle, fill, color=\ccolor, inner sep=1.25pt,
	label={right, xshift=0pt, yshift=0pt:{\small $(2,-1.5)$}}] at (axis cs:2,-1.5) {};

	\plot[domain=(-1:2), samples=100, color=\ccolor, line width=1pt, smooth, variable=\x]
	({\x},{newmyfunction(\x,0.5,1,1,0)});

	\end{axis}
	\end{tikzpicture}

\end{document}

