	ylabel style={above right},
	every axis x label/.style={at={(ticklabel* cs:1.02)}, anchor=west},
	every axis y label/.style={at={(ticklabel* cs:1.02)}, anchor=south}
	]

	% Old graph
	\node[circle, fill, color=gray, inner sep=1.25pt,
	label={above, xshift=0pt, opacity=0.5, yshift=0pt:{\small $(\newl,\fl)$}}] at (axis cs:\newl,\fl) {};

	\node[circle, fill, color=gray, inner sep=1.25pt,
	label={below, xshift=-0pt, opacity=0.5, yshift=0pt:{\small $(\newr,\fr)$}}] at (axis cs:\newr,\fr) {};

	\plot[domain=(\newl:\newr), samples=100, color=gray, line width=1pt, opacity=0.5, dashed, smooth, variable=\x]
	({\x},{newmyfunction(\x,\a,\b,\c,\d)});

	% New graph
	\node[circle, fill, color=\ccolor, inner sep=1.25pt,
	label={below, xshift=-0pt, yshift=0pt:{\small $(2,-1)$}}] at (axis cs:2,-1) {};

